using System;using System.Collections.Generic;using System.IO;using System.Reflection;using System.Web.Script.Serialization;
using BESHStatNG.ExcelCommon;using BESHStatNG.StatisticalProcessControl;
static class HelpersObserver47 {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;
 static Assembly tests;static List<object> rows=new List<object>();
 static object Form(string owner){return Activator.CreateInstance(tests.GetType("BESHStatNG.Test.Harness47."+owner+"Projection47",true),true);}
 static object Call(object f,string n,params object[] a){return f.GetType().GetMethod(n,F).Invoke(f,a);}
 static FieldInfo Field(object f,string n){for(var t=f.GetType();t!=null;t=t.BaseType){var p=t.GetField(n,F|BindingFlags.DeclaredOnly);if(p!=null)return p;}throw new MissingFieldException(n);}
 static object C(object f,string n){var p=f.GetType().GetProperty(n,F);return p!=null?p.GetValue(f,null):Field(f,n).GetValue(f);}
 static void Set(object f,string n,object v){for(var t=f.GetType();t!=null;t=t.BaseType){var p=t.GetProperty(n,F|BindingFlags.DeclaredOnly);if(p!=null){p.SetValue(f,v,null);return;}}Field(f,n).SetValue(f,v);}
 static void Check(bool value,string message){if(!value)throw new InvalidOperationException(message);}
 static void Main(string[] args){var lib=Path.GetFullPath(args[0]);AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{var p=Path.Combine(lib,new AssemblyName(e.Name).Name+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};tests=Assembly.LoadFrom(Path.Combine(lib,"BESHStatNG.Test.dll"));
  var m=Form("Ui18MMRM");var opt=Call(m,"ParseMMRMCovarianceOptimizerMode","");Check(opt.ToString()=="AverageInformationReml","MMRM default optimizer changed");rows.Add(new{method="ParseMMRMCovarianceOptimizerMode",actual=opt.ToString()});
  var grad=Call(m,"ParseMMRMCovarianceGradientMode","");Check(grad.ToString()=="Auto","MMRM default gradient changed");rows.Add(new{method="ParseMMRMCovarianceGradientMode",actual=grad.ToString()});
  var ctlType=typeof(BESHStatNG.regression.MixedModelControl);var ctl=Activator.CreateInstance(ctlType);var controlArgs=new object[]{ctl};Call(m,"ApplyMMRMCovarianceOptimizerSelections",controlArgs);Check(Object.ReferenceEquals(ctl,controlArgs[0]),"ByRef control identity changed");rows.Add(new{method="ApplyMMRMCovarianceOptimizerSelections",actual="SAME_CONTROL_WITH_CURRENT_DEFAULT_SELECTIONS"});
  for(int mask=0;mask<4;mask++){Field(m,"pMmrmCancelRequested").SetValue(m,(mask&1)!=0);Field(m,"pMmrmInterruptRequested").SetValue(m,(mask&2)!=0);var cancel=(bool)Call(m,"IsMMRMCancellationRequested");var interrupt=(bool)Call(m,"IsMMRMInterruptionRequested");Check(cancel==((mask&1)!=0)&&interrupt==((mask&2)!=0&&(mask&1)==0),"Mixed boundary flags changed");rows.Add(new{method="IsMMRMCancellationRequested+IsMMRMInterruptionRequested",mask=mask,cancel=cancel,interrupt=interrupt});}
  var pca=Form("Ui11PCA");for(int state=0;state<3;state++){Set(C(pca,"nudFAFactors"),"Value",3m);Set(C(pca,"nudFAEigen"),"Value",1.2m);Set(C(pca,"nudFAVariance"),"Value",90m);Set(C(pca,"optFAExtractEigen"),"Checked",state==1);Set(C(pca,"optFAExtractVariance"),"Checked",state==2);var method=Call(pca,"GetSelectedFARetentionMethod");var actual=(double)Call(pca,"GetSelectedFARetentionValue");Check(method.GetType().IsEnum&&actual==(state==1?1.2:state==2?90:3),"FA retention source choice changed");rows.Add(new{method="GetSelectedFARetentionMethod+GetSelectedFARetentionValue",state=state,actual=actual,choice=method.ToString()});}
  bool promax=false;for(int index=0;index<7;index++){Set(C(pca,"cbFARotation"),"SelectedIndex",index);var rotation=Call(pca,"GetSelectedFARotationMethod").ToString();var enabled=(bool)Field(C(pca,"nudFAPromaxPower"),"Enabled").GetValue(C(pca,"nudFAPromaxPower"));Check(enabled==(rotation=="Promax"),"Promax power option state changed");promax|=enabled;rows.Add(new{method="FactorAnalysisRotationChanged",index=index,rotation=rotation,powerEnabled=enabled});}Check(promax,"Promax positive branch omitted");
  var spc=Form("Ui21ControlCharts");foreach(SpcChartType chart in Enum.GetValues(typeof(SpcChartType))){var names=new[]{"IsAttributeChart","IsSubgroupChart","IsTimeWeightedChart","ChartCanUseSpecificationLines"};var expected=new[]{SpcRequestPreparation.IsAttributeChart(chart),SpcRequestPreparation.IsSubgroupChart(chart),SpcRequestPreparation.IsTimeWeightedChart(chart),SpcRequestPreparation.ChartCanUseSpecificationLines(chart)};for(int i=0;i<names.Length;i++){var actual=(bool)Call(spc,names[i],chart);Check(actual==expected[i],"SPC source wrapper destination changed");rows.Add(new{method=names[i],chart=chart.ToString(),actual=actual,expected=expected[i]});}}
  File.WriteAllText(args[1],new JavaScriptSerializer().Serialize(rows));
 }
}
